// 1. 状态接口与上下文
public interface OrderState {
    String name();
    void pay(Order order);
    void ship(Order order);
    void complete(Order order);
}
public class Order {
    private OrderState state;
    public Order(OrderState initial) { this.state = initial; }
    public void setState(OrderState s) { this.state = s; }
    public OrderState getState() { return state; }
    public void pay() { state.pay(this); }
    public void ship() { state.ship(this); }
    public void complete() { state.complete(this); }
}

// 2. 具体状态类：每个状态自己决定下一个状态 + 兜底非法事件
public class UnpaidState implements OrderState {
    public String name() { return "UNPAID"; }
    public void pay(Order o) {
        System.out.println("扣款成功");
        o.setState(new PaidState());
    }
    public void ship(Order o) {
        throw new IllegalStateException("UNPAID 不允许发货");
    }
    public void complete(Order o) {
        throw new IllegalStateException("UNPAID 不允许完成");
    }
}
public class PaidState implements OrderState {
    public String name() { return "PAID"; }
    public void pay(Order o) { throw new IllegalStateException("PAID 重复支付"); }
    public void ship(Order o) {
        System.out.println("已发货");
        o.setState(new ShippedState());
    }
    public void complete(Order o) { throw new IllegalStateException("PAID 未发货不能完成"); }
}
public class ShippedState implements OrderState {
    public String name() { return "SHIPPED"; }
    public void pay(Order o) { throw new IllegalStateException("SHIPPED 已发货"); }
    public void ship(Order o) { throw new IllegalStateException("SHIPPED 重复发货"); }
    public void complete(Order o) {
        System.out.println("订单完成");
        o.setState(new CompletedState());
    }
}

// 3. 转换表驱动的有限状态机（Table-Driven FSM）
public class OrderStateMachine {
    private final Map<String, Map<String, OrderState>> table = new HashMap<>();
    private final Map<String, OrderState> states = new HashMap<>();
    private OrderState current;
    public OrderStateMachine(OrderState initial) {
        register(initial);
        this.current = initial;
    }
    public void register(OrderState s) { states.put(s.name(), s); }
    public void addTransition(String from, String event, String to) {
        OrderState toState = states.get(to);
        if (toState == null) {
            throw new IllegalArgumentException("未注册目标状态: " + to);
        }
        table.computeIfAbsent(from, k -> new HashMap<>()).put(event, toState);
    }
    public void fire(String event) {
        Map<String, OrderState> row = table.get(current.name());
        OrderState next = (row == null) ? null : row.get(event);
        if (next == null) {
            throw new IllegalStateException(
                current.name() + " 上无事件 " + event + " 的合法转换");
        }
        this.current = next;
    }
    public OrderState current() { return current; }
}
